<!-- HEADER -->
<header>
  <div class="container">
    <h1>Nine Decades of Oscar-Winning Scores</h1>
    <p class="subtitle">A Historical Trend Analysis of Every Academy Award Best Original Score Winner, 1934&ndash;2026</p>
    <p class="meta">93 Ceremonies &middot; 69 Unique Composer Entries &middot; Data sourced from the Official Academy Awards Database</p>
  </div>
</header>

<!-- KPI CARDS -->
<div class="container">
  <div class="kpi-grid">
    <div class="kpi-card">
      <div class="kpi-value">69</div>
      <div class="kpi-label">Unique Composers</div>
      <div class="kpi-detail">across 93 ceremonies</div>
    </div>
    <div class="kpi-card">
      <div class="kpi-value">4</div>
      <div class="kpi-label">Max Wins (Single Composer)</div>
      <div class="kpi-detail">three-way tie: Barry, Williams, G&ouml;ransson</div>
    </div>
    <div class="kpi-card">
      <div class="kpi-value">25.8%</div>
      <div class="kpi-label">Repeat Winner Rate</div>
      <div class="kpi-detail">24 of 93 ceremonies</div>
    </div>
