(function() {
  const eras = {
    'Golden Age (1934-1960)': { min: 1934, max: 1960 },
    'Silver Age (1961-1980)': { min: 1961, max: 1980 },
    'Modern Era (1981-2000)': { min: 1981, max: 2000 },
    'Contemporary (2001-2026)': { min: 2001, max: 2026 }
  };

  const eraData = {};
  for (const [name, range] of Object.entries(eras)) {
    eraData[name] = { total: 0, composers: new Set(), repeatWins: 0 };
  }

  const runningCount = {};
  data.forEach(d => {
    for (const [name, range] of Object.entries(eras)) {
      if (d.year >= range.min && d.year <= range.max) {
        eraData[name].total++;
        eraData[name].composers.add(d.composer);
        runningCount[d.composer] = (runningCount[d.composer] || 0) + 1;
        if (runningCount[d.composer] > 1) eraData[name].repeatWins++;
      }
    }
  });

  const eraLabels = Object.keys(eras);

  new Chart(document.getElementById('eraChart'), {
